// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Force random==1: block.timestamp and block.difficulty are set to make hash mod 2 == 1
        vm.warp(1);
        vm.difficulty(2); // keccak256(abi.encodePacked(1,2)) % 2 == 1
        vm.deal(address(this), 10);
        vm.prank(address(this));
        c.play{value: 10}();
        // Reference: play does nothing when random==1, so pot remains 10.
        // Bug: else branch sends funds and sets pot=0, so pot becomes 0.
        assertEq(c.pot(), 10);
    }
}

