    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a player
        address player = address(0x1234);
        vm.deal(player, 10 ether);

        // We need to force the random outcome to 0.
        // Since random is (block.timestamp ^ block.difficulty) % 2, we can set:
        // block.timestamp = 2, block.difficulty = 2 → (keccak256(2,2) % 2) could be 0.
        // But easier: call play twice with different parameters to ensure at least one loss.
        // Actually we just need a loss scenario. We'll call play and then check pot.

        vm.warp(2);
        vm.roll(2);
        vm.prank(player);
        c.play{value: 10 ether}();

        // For the reference: after a loss (random == 0), pot becomes 0 and bank gets fee, player gets pot-fee.
        // For the buggy: after the if block, the code executes the same distribution again, which would
        // try to transfer pot (now 0) minus fee, but pot is 0, so transfer(0 - 1) reverts due to underflow?
        // Actually transfer with uint256 underflow reverts. But the buggy version sets pot = 0 after the if,
        // then does the same again: payable(bank).transfer(FEE_AMOUNT) sends 1 wei from contract (already transferred),
        // then payable(msg.sender).transfer(pot - FEE_AMOUNT) where pot is already 0, so underflow revert.
        // So the call reverts. We must catch it.

        // We'll check the pot after a single play. In reference, pot = 10 (still? no, after loss it's 0).
        // In buggy, the call reverts, so state unchanged? Actually if revert occurs mid-transaction,
        // all state changes revert, so pot remains as before the call. But before call pot = 0.
        // Actually before any play, pot = 0. After the call in reference: pot = 0. In buggy: call reverts, pot stays 0.
        // That's same! Need different scenario.

        // Alternative: make two consecutive calls with deals.
        // Let's reset and do a sequence that leads to observable divergence in pot.
    }
}

