    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(1);
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.play{value: 10}();

        uint256 potAfter = c.pot();
        assertTrue(potAfter == 0);
    }
}

