contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use vm.warp and vm.roll to set block.timestamp and block.difficulty to control random == 0.
        vm.warp(123456);
        vm.roll(789);
        // Call play() with exactly 10 wei from a non-bank user.
        vm.deal(address(0x1), 10);
        vm.prank(address(0x1));
        c.play{value: 10}();
